import { fileURLToPath } from 'node:url';
import { drizzle, type PostgresJsDatabase } from 'drizzle-orm/postgres-js';
import { migrate } from 'drizzle-orm/postgres-js/migrator';
import postgres from 'postgres';
import * as schema from './schema';

/** Connections kept open to PostgreSQL (the game writes from one queue at a time). */
const POOL_SIZE = 4;
/** SQL migrations generated by `pnpm db:generate`. */
const MIGRATIONS_FOLDER = fileURLToPath(new URL('../../drizzle', import.meta.url));

export type Database = PostgresJsDatabase<typeof schema>;

export interface DatabaseConnection {
  db: Database;
  close(): Promise<void>;
}

/** Connects to PostgreSQL and applies the migrations not applied yet. */
export async function openDatabase(url: string): Promise<DatabaseConnection> {
  const client = postgres(url, { max: POOL_SIZE, onnotice: () => {} });
  const db = drizzle(client, { schema });
  try {
    await migrate(db, { migrationsFolder: MIGRATIONS_FOLDER });
  } catch (error) {
    await client.end();
    throw error;
  }
  return { db, close: () => client.end() };
}
